WITH metrics AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY plan ORDER BY end_date DESC, id) AS row_seq, ROUND(monthly_fee / SUM(monthly_fee) OVER (PARTITION BY status), 4) AS monthly_fee_share FROM subscriptions) SELECT DATE_TRUNC('WEEK', start_date) AS week_start, DATE_TRUNC('QUARTER', start_date) AS quarter_start, ROUND(AVG(monthly_fee_share), 2) AS avg_monthly_fee_share, PERCENTILE_APPROX(monthly_fee, 0.9) AS monthly_fee_p90, ROUND(SUM(monthly_fee_share) / NULLIF(COUNT(CASE WHEN status = 'EXPIRED' THEN 1 END), 0), 2) AS monthly_fee_share_per_expired, SIZE(COLLECT_SET(status)) AS num_status, GROUPING_ID() AS grouping_level FROM metrics GROUP BY GROUPING SETS ((DATE_TRUNC('WEEK', start_date), DATE_TRUNC('QUARTER', start_date)), (DATE_TRUNC('WEEK', start_date))) ORDER BY week_start DESC NULLS FIRST
